<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle title="Coaching Feedback Details" class="col-span-2" show-doc />
    <div class="col-span-2 flex flex-wrap justify-between items-center gap-4">
      <GoBackButton subject="coaching feedbacks" :fallback-to="{ name: 'coaching-feedbacks' }" />
      <div v-if="feedback" class="flex gap-2">
        <Badge :variant="getFeedbackTypeBadge(feedback.type).variant">
          {{ getFeedbackTypeBadge(feedback.type).label }}
        </Badge>
        <Badge :variant="getFeedbackTriggerBadge(feedback.trigger).variant">
          {{ getFeedbackTriggerBadge(feedback.trigger).label }}
        </Badge>
      </div>
    </div>
    <AppLoader v-if="isLoading" class="col-span-2" subject="coaching feedback details" />
    <AppError v-else-if="error" :error="error" title="Failed to load coaching feedback details" class="col-span-2" />
    <AppEmpty v-else-if="!feedback" class="col-span-2" subject="coaching feedback details" />
    <Card v-else class="grid col-span-2">
      <CardContent class="flex flex-col gap-4">
        <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          <LabeledEntityDate label="Created at" :date="feedback.created_at" />
          <LabeledEntityUser v-if="feedback.user_id" :user-id="feedback.user_id" />
          <LabeledEntityProject v-if="feedback.project_id" label="Project" :project-id="feedback.project_id" />
          <LabeledEntityWorkShift
            v-if="feedback.workshift_id"
            label="Work Shift"
            :work-shift-id="feedback.workshift_id"
          />
        </div>
        <template v-if="feedback.period_start || feedback.period_end">
          <Separator />
          <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
            <LabeledValue v-if="feedback.period_start" label="Period Start" :value="feedback.period_start" />
            <LabeledValue v-if="feedback.period_end" label="Period End" :value="feedback.period_end" />
          </div>
        </template>
        <Separator />
        <LabeledValue label="Message" value-class="line-clamp-none whitespace-pre-wrap">
          {{ feedback.message }}
        </LabeledValue>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { getCoachingFeedbackDetails, type GetCoachingFeedbackDetailsResponse } from '~/client';
import { getFeedbackTypeBadge } from '~/constants/coaching-feedbacks/feedbackTypeConfig';
import { getFeedbackTriggerBadge } from '~/constants/coaching-feedbacks/feedbackTriggerConfig';

definePageMeta({
  roles: ['admin'],
  backLabel: 'coaching feedback',
});

useHead({
  title: 'Coaching Feedback Details',
});

const route = useRoute('coaching-feedbacks-id');
const feedbackId = computed(() => route.params.id?.toString() || '');

const {
  data: feedback,
  error,
  isLoading,
} = useQuery({
  key: () => ['coaching-feedback-details', feedbackId.value],
  query: (): Promise<GetCoachingFeedbackDetailsResponse> =>
    getCoachingFeedbackDetails({ composable: '$fetch', path: { feedback_id: feedbackId.value } }),
  staleTime: 0,
  enabled: computed(() => !!feedbackId.value && route.name === 'coaching-feedbacks-id'),
});
</script>
